def choose_move(observation):
    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = max(corners, key=lambda p: abs(p[0] - ox) + abs(p[1] - oy))
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets, sx, sy)
        if target is None:
            target = pos(observation.get("objective_position"), None)
        if target is None:
            return [0, 0]
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(resources, sx, sy)
    if target is None:
        if observation.get("safe_move_toward_center", False) and gw and gh:
            target = (gw // 2, gh // 2)
        elif observation.get("avoid_opponent", True):
            target = (sx + clamp_step(ox, sx), sy + clamp_step(oy, sy))
        else:
            return [0, 0]
    return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

